class_name StatsTracker
extends RefCounted

var total_correct: int = 0
var total_answered: int = 0


func track(correct: bool) -> void:
	total_answered += 1
	if correct:
		total_correct += 1


func get_accuracy() -> float:
	if total_answered == 0:
		return 0.0
	return (float(total_correct) / float(total_answered)) * 100.0

